-- 05_load_dimensions.sql  -  DIMENSION LOAD (project_staging.stg_* -> project_dw.dim_*)
-- Surrogate keys are generated by the database (identity columns); the business key is kept as a unique column.
--   Example:  customer_email = amygreen@example.com   ->   customer_key = 1001
SET search_path TO project_dw, project_staging;

-- Full refresh: empty all warehouse tables and restart the surrogate key counters
TRUNCATE fact_customer_merchant, fact_daily_fraud_snapshot, fact_transactions,
         dim_date, dim_time, dim_customer, dim_merchant, dim_transactiontype, dim_behaviorrisk RESTART IDENTITY CASCADE;

-- ---------- dim_date : one row per calendar day between the first and last transaction ----------
INSERT INTO dim_date (date_key, full_date, day_of_month, day_name, week_of_year, month_number, month_name, quarter, year, is_weekend)
SELECT TO_CHAR(d, 'YYYYMMDD')::INTEGER, d::DATE,
       EXTRACT(DAY FROM d)::SMALLINT, TRIM(TO_CHAR(d, 'Day')), EXTRACT(WEEK FROM d)::SMALLINT,
       EXTRACT(MONTH FROM d)::SMALLINT, TRIM(TO_CHAR(d, 'Month')), EXTRACT(QUARTER FROM d)::SMALLINT,
       EXTRACT(YEAR FROM d)::SMALLINT, EXTRACT(ISODOW FROM d) IN (6,7)
FROM generate_series((SELECT MIN(txn_timestamp)::DATE FROM stg_transaction_type),
                     (SELECT MAX(txn_timestamp)::DATE FROM stg_transaction_type), INTERVAL '1 day') AS g(d);

-- ---------- dim_time : 24 hours ----------
INSERT INTO dim_time (time_key, hour_of_day, hour_label, day_part)
SELECT h, h, LPAD(h::TEXT,2,'0') || ':00-' || LPAD(h::TEXT,2,'0') || ':59',
       CASE WHEN h < 6 THEN 'Night' WHEN h < 12 THEN 'Morning' WHEN h < 18 THEN 'Afternoon' ELSE 'Evening' END
FROM generate_series(0, 23) AS g(h);

-- ---------- dim_customer : surrogate key from 1001 ----------
INSERT INTO dim_customer (customer_email, customer_name, device_type, card_expiry_month, card_expiry_year)
SELECT customer_email, customer_name, device_type, card_expiry_month, card_expiry_year
FROM stg_customer ORDER BY customer_email;

-- ---------- dim_merchant : surrogate key from 5001 ----------
INSERT INTO dim_merchant (merchant_email, merchant_name)
SELECT merchant_email, merchant_name FROM stg_merchant ORDER BY merchant_email;

-- ---------- dim_transactiontype : type + region + IP prefix ----------
INSERT INTO dim_transactiontype (type_name, money_direction, location_region, ip_prefix)
SELECT DISTINCT type_name,
       CASE type_name WHEN 'Deposit' THEN 'Inflow' WHEN 'Withdrawal' THEN 'Outflow' WHEN 'Payment' THEN 'Outflow'
                      WHEN 'Transfer' THEN 'Transfer' ELSE 'Other' END,
       location_region, ip_prefix
FROM stg_transaction_type
ORDER BY 1, 3, 4;

-- ---------- dim_behaviorrisk : banded behaviour attributes (mini-dimension) ----------
INSERT INTO dim_behaviorrisk (purchase_pattern, anomaly_level, login_frequency_band, session_duration_band)
SELECT DISTINCT purchase_pattern, anomaly_level, login_frequency_band, session_duration_band
FROM stg_behavior_risk
ORDER BY 1, 2, 3, 4;

ANALYZE dim_date; ANALYZE dim_time; ANALYZE dim_customer; ANALYZE dim_merchant; ANALYZE dim_transactiontype; ANALYZE dim_behaviorrisk;
